import java.util.ArrayList;
import java.util.List;

public class SerialDeepCopierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static <T extends java.io.Serializable> T copyOf(T value) {
        try {
            return SerialDeepCopier.deepCopy(value);
        } catch (Exception e) {
            System.out.println("FAIL  deepCopy threw " + e.getClass().getSimpleName());
            failures++;
            return null;
        }
    }

    public static void main(String[] args) {
        List<String> members = new ArrayList<>();
        members.add("ann");
        members.add("bo");
        Team original = new Team("Reds", members);

        Team copy = copyOf(original);
        check("copy has same content", "Reds[ann, bo]", copy == null ? "null" : copy.toString());
        check("copy is a different object", true, copy != null && copy != original);
        check("member list is a different object", true, copy != null && copy.members != original.members);

        if (copy != null) {
            copy.members.add("cy");
            copy.name = "Blues";
        }
        check("original list untouched", 2, original.members.size());
        check("original name untouched", "Reds", original.name);
        check("copy really changed", 3, copy == null ? -1 : copy.members.size());

        ArrayList<String> words = new ArrayList<>();
        words.add("alpha");
        words.add("beta");
        ArrayList<String> wordsCopy = copyOf(words);
        check("list copy content", "[alpha, beta]", wordsCopy == null ? "null" : wordsCopy.toString());
        check("list copy is separate", true, wordsCopy != null && wordsCopy != words);

        check("string copy", "hello", copyOf("hello"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

